basic.code:
data "aws_vpc" "default" {
  default = true
}

resource "aws_instance" "app" {
  ami           = "ami-123456"
  instance_type = "t3.micro"
  subnet_id     = data.aws_vpc.default.id
}

variable "instance_type" {
  type    = string
  default = "t3.micro"
}

resource "aws_instance" "app" {
  instance_type = var.instance_type
}

variable "region" {
  type    = string
  default = "us-east-1"
}

provider "aws" {
  region = var.region
}

resource "aws_instance" "app" {
  ami           = var.ami
  instance_type = "t3.micro"

  lifecycle {
    create_before_destroy = true
  }
}

advanced.code:
resource "aws_subnet" "s" {
  for_each = { for n in var.names : n => n }
  vpc_id   = aws_vpc.main.id
}

# Bad pattern: keys derived from apply-time values
